//! SPICE-6 reference suite: every `tests/reference/<name>.cir` is simulated by bb-spice and
//! compared with ngspice golden data (`<name>.raw`, `<name>.meas`) generated by
//! `scripts/regen-spice-golden.sh`.
//!
//! Tolerances (SPEC SPICE-6): `.op`/`.dc`/`.tf` within 0.1 % or 1 µV / 1 nA; `.ac` within
//! 0.5 % magnitude and 0.5° phase; `.tran` within 1 % normalised RMS error. Noise spectra use
//! 1 % and `.meas` results 1 % (ngspice prints them with 6 digits and measures `avg/rms` up to
//! the next time point rather than exactly at `to=`).

use bb_spice::export::{read_meas_log, read_raw};
use bb_spice::{Netlist, ParseOptions, Plot, PlotKind, Results};
use std::path::{Path, PathBuf};

fn ref_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/reference")
}

fn abs_floor(name: &str) -> f64 {
    if name.starts_with("i(") || name.starts_with('@') {
        1e-9
    } else {
        1e-6
    }
}

#[derive(Default)]
struct Report {
    errors: Vec<String>,
    compared: usize,
    worst: Vec<(String, f64)>,
}

impl Report {
    fn fail(&mut self, msg: String) {
        self.errors.push(msg);
    }
}

fn interp(xs: &[f64], ys: &[f64], x: f64) -> f64 {
    bb_spice::meas::interp(xs, ys, x)
}

fn compare_plot(r: &mut Report, ctx: &str, g: &Plot, o: &Plot) {
    let mut any = false;
    for gv in &g.vectors {
        if g.has_scale && std::ptr::eq(gv, &g.vectors[0]) {
            continue;
        }
        let Some(ov) = o.vector(&gv.name) else {
            continue;
        };
        any = true;
        r.compared += 1;
        let name = &gv.name;
        match g.kind {
            PlotKind::Op | PlotKind::Tf | PlotKind::Dc => {
                if gv.len() != ov.len() {
                    r.fail(format!(
                        "{ctx} {name}: {} points vs ngspice {}",
                        ov.len(),
                        gv.len()
                    ));
                    continue;
                }
                let floor = if g.kind == PlotKind::Tf {
                    1e-9
                } else {
                    abs_floor(name)
                };
                let mut worst = 0.0f64;
                for i in 0..gv.len() {
                    let (a, b) = (ov.real_at(i), gv.real_at(i));
                    let tol = (1e-3 * b.abs()).max(floor);
                    let err = (a - b).abs() / tol;
                    worst = worst.max(err);
                    if err > 1.0 {
                        r.fail(format!("{ctx} {name}[{i}]: {a:.9e} vs ngspice {b:.9e}"));
                        break;
                    }
                }
                r.worst.push((format!("{ctx} {name}"), worst));
            }
            PlotKind::NoiseTotal | PlotKind::Noise => {
                if gv.len() != ov.len() {
                    r.fail(format!(
                        "{ctx} {name}: {} points vs ngspice {}",
                        ov.len(),
                        gv.len()
                    ));
                    continue;
                }
                let mut worst = 0.0f64;
                for i in 0..gv.len() {
                    let (a, b) = (ov.real_at(i), gv.real_at(i));
                    let err = (a - b).abs() / (1e-2 * b.abs()).max(1e-30);
                    worst = worst.max(err);
                    if err > 1.0 {
                        r.fail(format!("{ctx} {name}[{i}]: {a:.6e} vs ngspice {b:.6e}"));
                        break;
                    }
                }
                r.worst.push((format!("{ctx} {name}"), worst));
            }
            PlotKind::Ac => {
                if gv.len() != ov.len() {
                    r.fail(format!(
                        "{ctx} {name}: {} points vs ngspice {}",
                        ov.len(),
                        gv.len()
                    ));
                    continue;
                }
                let maxmag = (0..gv.len())
                    .map(|i| gv.complex_at(i).abs())
                    .fold(0.0, f64::max);
                let mut worst = 0.0f64;
                for i in 0..gv.len() {
                    let (a, b) = (ov.complex_at(i), gv.complex_at(i));
                    let (ma, mb) = (a.abs(), b.abs());
                    let floor = 1e-6 * maxmag + 1e-15;
                    let em = (ma - mb).abs() / (5e-3 * mb).max(floor);
                    let mut ep = 0.0;
                    if mb > 1e-4 * maxmag {
                        let mut d = (a.arg() - b.arg()).to_degrees();
                        while d > 180.0 {
                            d -= 360.0;
                        }
                        while d < -180.0 {
                            d += 360.0;
                        }
                        ep = d.abs() / 0.5;
                    }
                    worst = worst.max(em).max(ep);
                    if em > 1.0 || ep > 1.0 {
                        r.fail(format!(
                            "{ctx} {name}[{i}] f={:.4e}: |{ma:.6e}|∠{:.3}° vs ngspice |{mb:.6e}|∠{:.3}°",
                            g.scale_at(i),
                            a.arg().to_degrees(),
                            b.arg().to_degrees()
                        ));
                        break;
                    }
                }
                r.worst.push((format!("{ctx} {name}"), worst));
            }
            PlotKind::Tran => {
                let gx = g.scale_values();
                let ox = o.scale_values();
                let gy = gv.reals();
                let oy = ov.reals();
                let (mn, mx) = gy
                    .iter()
                    .fold((f64::INFINITY, f64::NEG_INFINITY), |(a, b), &y| {
                        (a.min(y), b.max(y))
                    });
                let amax = gy.iter().fold(0.0f64, |a, &y| a.max(y.abs()));
                let range = (mx - mn).max(1e-3 * amax).max(abs_floor(name));
                let mut sum = 0.0;
                for (k, &t) in gx.iter().enumerate() {
                    let d = interp(&ox, &oy, t) - gy[k];
                    sum += d * d;
                }
                let nrms = (sum / gx.len().max(1) as f64).sqrt() / range;
                r.worst.push((format!("{ctx} {name}"), nrms / 0.01));
                if nrms > 0.01 {
                    r.fail(format!(
                        "{ctx} {name}: NRMS error {:.3} % (range {range:.4e})",
                        nrms * 100.0
                    ));
                }
            }
        }
    }
    if !any {
        r.fail(format!(
            "{ctx}: no vectors in common (ngspice has {:?})",
            g.names().collect::<Vec<_>>()
        ));
    }
}

fn run_reference(name: &str) -> Report {
    let dir = ref_dir();
    let text = std::fs::read_to_string(dir.join(format!("{name}.cir"))).expect("netlist");
    let opts = ParseOptions {
        base_dir: Some(dir.clone()),
        file_name: Some(format!("{name}.cir")),
        ..Default::default()
    };
    let nl =
        Netlist::parse_with(&text, &opts).unwrap_or_else(|e| panic!("{name}: parse error: {e}"));
    let res: Results = nl
        .run()
        .unwrap_or_else(|e| panic!("{name}: simulation failed: {e}"));
    let golden_text =
        std::fs::read_to_string(dir.join(format!("{name}.raw"))).unwrap_or_else(|_| {
            panic!("{name}: missing golden data; run scripts/regen-spice-golden.sh")
        });
    let golden = read_raw(&golden_text).expect("golden rawfile");
    let ours: Vec<&Plot> = res.runs.iter().flat_map(|r| r.plots.iter()).collect();
    let mut r = Report::default();
    // pair the k-th plot of each kind
    let kinds = [
        PlotKind::Op,
        PlotKind::Dc,
        PlotKind::Tran,
        PlotKind::Ac,
        PlotKind::Noise,
        PlotKind::NoiseTotal,
        PlotKind::Tf,
    ];
    for kind in kinds {
        let g: Vec<&Plot> = golden.iter().filter(|p| p.kind == kind).collect();
        let o: Vec<&Plot> = ours.iter().copied().filter(|p| p.kind == kind).collect();
        if g.len() != o.len() {
            r.fail(format!(
                "{name}: {} {:?} plots vs ngspice {}",
                o.len(),
                kind,
                g.len()
            ));
            continue;
        }
        for (k, (gp, op)) in g.iter().zip(o.iter()).enumerate() {
            compare_plot(&mut r, &format!("{name} {:?}#{k}", kind), gp, op);
        }
    }
    // measurements
    let meas_path = dir.join(format!("{name}.meas"));
    if let Ok(mt) = std::fs::read_to_string(&meas_path) {
        let golden_meas = read_meas_log(&mt);
        let run = &res.runs[0];
        for (mname, gv) in golden_meas {
            let Some(ov) = run.measure(&mname) else {
                r.fail(format!(
                    "{name}: measurement `{mname}` missing or failed: {:?}",
                    run.measures.iter().find(|m| m.name == mname)
                ));
                continue;
            };
            r.compared += 1;
            let tol = (1e-2 * gv.abs()).max(1e-9);
            r.worst
                .push((format!("{name} meas {mname}"), (ov - gv).abs() / tol));
            if (ov - gv).abs() > tol {
                r.fail(format!(
                    "{name}: meas {mname} = {ov:.6e} vs ngspice {gv:.6e}"
                ));
            }
        }
    }
    r
}

fn check(name: &str) {
    let r = run_reference(name);
    let mut worst = r.worst.clone();
    worst.sort_by(|a, b| b.1.total_cmp(&a.1));
    if !r.errors.is_empty() {
        panic!(
            "{name}: {} failure(s) ({} vectors compared):\n  {}\nworst (fraction of tolerance): {:?}",
            r.errors.len(),
            r.compared,
            r.errors
                .iter()
                .take(12)
                .cloned()
                .collect::<Vec<_>>()
                .join("\n  "),
            worst.iter().take(5).collect::<Vec<_>>()
        );
    }
    eprintln!(
        "{name}: {} vectors within tolerance; worst {:?}",
        r.compared,
        worst.first()
    );
}

macro_rules! reference {
    ($($name:ident),* $(,)?) => {
        $(
            #[test]
            fn $name() {
                check(stringify!($name));
            }
        )*

        #[test]
        fn suite_is_complete() {
            let listed = [$(stringify!($name)),*];
            assert!(listed.len() >= 30, "SPICE-6 needs at least 30 reference circuits");
            for entry in std::fs::read_dir(ref_dir()).unwrap() {
                let p = entry.unwrap().path();
                let f = p.file_name().unwrap().to_string_lossy().to_string();
                if let Some(base) = f.strip_suffix(".cir") {
                    if base.ends_with(".ngspice") {
                        continue;
                    }
                    assert!(listed.contains(&base), "reference circuit {f} is not listed in tests/reference.rs");
                    assert!(ref_dir().join(format!("{base}.raw")).exists(), "{base}.raw missing: run scripts/regen-spice-golden.sh");
                }
            }
        }
    };
}

